/* From Uiverse.io by Smit-Prajapati - Tags: card, cool card, card animation, card hover, simple cards, card design */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 230px;
  height: 300px;
  background: linear-gradient(-45deg, rgb(0, 153, 255) 0%, cyan 100%);
  overflow: hidden;
  border: 1px solid black;
  box-shadow: rgba(141, 177, 205, 0.618) 0px 40px 30px -25px;
  transition: all 0.5s cubic-bezier(0.785, 0.135, 0.15, 0.86);
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.08);
  box-shadow: rgba(141, 177, 205, 0.618) 0px 30px 30px -25px;
}

.__UIV_SCOPE__ .icons-container {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding: 1rem;
  z-index: 999;
}

.__UIV_SCOPE__ .icons-container .svg {
  stroke: white;
  width: 20px;
  transition: transform 0.5s cubic-bezier(0.785, 0.135, 0.15, 0.86);
}

.__UIV_SCOPE__ .icons-container .svg:hover {
  transform: scale(1.5);
  stroke: black;
}

.__UIV_SCOPE__ .icons-container .twitter {
  fill: white;
}

.__UIV_SCOPE__ .icons-container .twitter:hover {
  fill: black;
  stroke: none;
}

.__UIV_SCOPE__ .logo {
  width: 50px;
  padding: 1rem;
}

.__UIV_SCOPE__ .logo .svg {
  fill: white;
}

.__UIV_SCOPE__ .title {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: White;
  font-weight: bold;
  font-size: 1.1rem;
}

.__UIV_SCOPE__ .box {
  position: absolute;
  width: 100%;
  height: 100%;
  box-shadow: rgba(66, 66, 66, 0.349) 5px 0px 10px 0px inset;
  transition: all 0.5s ease-in-out;
  display: grid;
  place-content: center;
  padding: 2rem 2rem 3rem 2rem;
  border: 1px solid black;
}

.__UIV_SCOPE__ .box .content {
  position: relative;
  transform: translateY(-100%);
  opacity: 0;
  transition: all 0.5s ease-in-out 0.3s;
}

.__UIV_SCOPE__ .box .content .box-title {
  display: block;
  color: white;
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 1rem;
}

.__UIV_SCOPE__ .box .content .box-text {
  color: rgba(255, 255, 255, 0.738);
  font-size: 0.8rem;
}

.__UIV_SCOPE__ .box:hover {
  right: 0;
  top: 0;
  border-radius: 0;
  border: 1px solid transparent;
  box-shadow: rgba(66, 66, 66, 0) 5px 0px 10px 0px inset;
}

.__UIV_SCOPE__ .box:hover .content {
  transform: translate(0, 0);
  opacity: 1;
}

.__UIV_SCOPE__ .box1 {
  top: -85%;
  right: -40%;
  background: rgb(255, 112, 60);
  border-radius: 200px;
}

.__UIV_SCOPE__ .box2 {
  top: -70%;
  right: -45%;
  background: rgb(255, 174, 0);
  border-radius: 200px;
}

.__UIV_SCOPE__ .box3 {
  top: -62%;
  right: -30%;
  background: rgb(255, 194, 52);
  border-radius: 200px;
}
